const box = { size: 1, items: ["a"] };
Object.seal(box);
box.size = 2;

Object.freeze(box);
box.items.push("b");

console.log(box.size);
console.log(box.items.join(","));
console.log(Object.isSealed(box), Object.isFrozen(box));
console.log(Object.isFrozen(Object.preventExtensions({})));
